import pathlib
r=pathlib.Path('.')
def put(p,s):
 p=r/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf-8')
put('components/Header.tsx', ''''use client';
import {ArrowUpRight,Menu,X} from 'lucide-react';import Link from 'next/link';import {useEffect,useState} from 'react';import {usePathname} from 'next/navigation';
export default function Header(){const path=usePathname();const [menuPath,setMenuPath]=useState<string|null>(null);const open=menuPath===path;const [scrolled,setScrolled]=useState(false);
useEffect(()=>{const fn=()=>setScrolled(window.scrollY>40);fn();window.addEventListener('scroll',fn,{passive:true});return()=>window.removeEventListener('scroll',fn)},[]);
useEffect(()=>{if(!open)return;const previous=document.body.style.overflow;const desktop=matchMedia('(min-width:1101px)');if(!desktop.matches)document.body.style.overflow='hidden';const close=()=>{if(desktop.matches)setMenuPath(null)};desktop.addEventListener('change',close);const key=(e:KeyboardEvent)=>{if(e.key==='Escape'){setMenuPath(null);document.querySelector<HTMLButtonElement>('.menu-toggle')?.focus()}if(e.key==='Tab'){const items=Array.from(document.querySelectorAll<HTMLElement>('.header a,.menu-toggle')).filter(el=>el.getClientRects().length>0);const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};window.addEventListener('keydown',key);return()=>{document.body.style.overflow=previous;desktop.removeEventListener('change',close);window.removeEventListener('keydown',key)}},[open]);
return <header className={scrolled?'header solid':'header'}><Link href="/" className="brand" onClick={()=>setMenuPath(null)}>REVIVE<span>AESTHETICS CLINIC</span></Link><nav id="main-navigation" aria-label="Main navigation" className={open?'nav open':'nav'}>{[['Treatments','/treatments'],['Our Clinic','/about'],['Specialists','/specialists'],['Journal','/journal'],['Client voices','/reviews'],['Contact','/contact']].map(([n,u])=><Link key={u} href={u} onClick={()=>setMenuPath(null)}>{n}</Link>)}<Link className="nav-book" href="/online-consultation" onClick={()=>setMenuPath(null)}>Book online<ArrowUpRight size={18} aria-hidden="true"/></Link></nav><button className="menu-toggle" aria-controls="main-navigation" aria-label={open?'Close navigation':'Open navigation'} aria-expanded={open} onClick={()=>setMenuPath(open?null:path)}><span>{open?'Close':'Menu'}</span>{open?<X size={20} aria-hidden="true"/>:<Menu size={20} aria-hidden="true"/>}</button></header>}
''')
p=r/'lib/config.ts';s=p.read_text(encoding='utf-8').replace('whatsapp: null',"whatsapp: {number: process.env.NEXT_PUBLIC_WHATSAPP_NUMBER || '', verified: process.env.NEXT_PUBLIC_WHATSAPP_VERIFIED === 'true', placeholder: '+92 XXX XXXXXXX'}, onlineConsultation: {feePKR: 0, feeConfirmed: false}");put('lib/config.ts',s)
put('lib/booking.ts', '''import {clinic} from './config';
export function whatsappBookingUrl(){const {number,verified}=clinic.whatsapp;const digits=number.replace(/[+\\s()-]/g,'');if(!verified||!/^\\d{10,15}$/.test(digits))return null;const message='Hello Revive, I would like to book an online consultation. Please confirm practitioner availability, the fee and payment instructions before I make payment.';return `https://wa.me/${digits}?text=${encodeURIComponent(message)}`}
''')
put('components/BookingAction.tsx', '''import {MessageCircle,Phone,ArrowUpRight} from 'lucide-react';import {whatsappBookingUrl} from '@/lib/booking';import {clinic} from '@/lib/config';
export default function BookingAction(){const url=whatsappBookingUrl();return <div className="booking-action">{url?<a className="button" href={url} target="_blank" rel="noreferrer"><MessageCircle size={20} aria-hidden="true"/>Confirm availability on WhatsApp<ArrowUpRight size={18} aria-hidden="true"/></a>:<><div className="whatsapp-pending"><MessageCircle size={22} aria-hidden="true"/><div><strong>WhatsApp booking — number pending</strong><span>{clinic.whatsapp.placeholder}</span></div></div><p>The WhatsApp booking link will be available once the clinic number is confirmed. No booking has been submitted.</p><a className="button" href={clinic.telephone}><Phone size={18} aria-hidden="true"/>Call to confirm booking details<ArrowUpRight size={18} aria-hidden="true"/></a></>}</div>}
''')
put('app/online-consultation/page.tsx', '''import {CalendarDays,MessageCircle,ReceiptText,Video,ArrowUpRight,ShieldCheck} from 'lucide-react';import Link from 'next/link';import BookingAction from '@/components/BookingAction';import {clinic} from '@/lib/config';import {meta} from '@/lib/seo';
export const metadata=meta('Book an Online Consultation','Enquire about an online consultation with Revive. Confirm availability, the consultation fee and payment instructions before booking.','/online-consultation');
export default function Page(){return <div className="section page online-page"><span className="eyebrow">REVIVE / CARE, WHEREVER YOU ARE</span><h1>A conversation.<br/><em>Closer than you think.</em></h1><p className="lede">Request an online consultation through WhatsApp. Confirm the practitioner, availability and fee before you make a payment.</p><div className="online-grid"><section className="online-process"><h2>How to book online</h2>{[{icon:MessageCircle,title:'Confirm availability',copy:'Message the clinic on WhatsApp with your preferred date and a brief reason for the consultation. Confirm who will consult with you and whether an online appointment is appropriate.'},{icon:CalendarDays,title:'Agree the details',copy:'Confirm the date, time and time zone, consultation fee, payment method, and cancellation or rescheduling terms directly with the clinic.'},{icon:ReceiptText,title:'Pay, then share confirmation',copy:'After the clinic confirms availability and provides payment instructions, make the agreed payment. Send your payment receipt on WhatsApp so the clinic can verify it. Do not send card details or bank login information.'},{icon:Video,title:'Receive your appointment confirmation',copy:'The clinic will confirm receipt and share your appointment details and joining instructions. Your appointment is confirmed only when the clinic confirms it.'}].map(({icon:Icon,title,copy},i)=><div className="online-step" key={title}><div className="online-step-icon"><Icon size={24} aria-hidden="true"/><span>0{i+1}</span></div><div><h3>{title}</h3><p>{copy}</p></div></div>)}</section><aside className="online-booking-panel"><span className="eyebrow">ONLINE CONSULTATION</span><h2>Let’s find<br/><em>a time for you.</em></h2><div className="consultation-fee"><span>Consultation fee</span><strong>PKR {clinic.onlineConsultation.feePKR}</strong><small>Provisional amount — fee not yet confirmed. Confirm the actual fee before payment; this is not an offer of a free consultation.</small></div><BookingAction/><div className="online-note"><ShieldCheck size={20} aria-hidden="true"/><p>Share only the information needed to arrange your appointment. Ask the clinic how to send sensitive medical information securely.</p></div></aside></div><div className="online-limit"><h3>Is online care right for your concern?</h3><p>Some concerns require an in-person assessment, examination or tests. An online consultation does not guarantee a prescription or procedure. Ask the clinic whether this format is suitable for you.</p><Link href="/contact" className="text-link">Prefer to visit the clinic?<ArrowUpRight size={18} aria-hidden="true"/></Link></div></div>}
''')
put('app/reviews/page.tsx', '''import {Quote,MessageCircle,ArrowUpRight,ShieldCheck} from 'lucide-react';import Link from 'next/link';import {reviews} from '@/lib/trust';import {meta} from '@/lib/seo';
export const metadata=meta('What Our Clients Say','Client experiences at Revive Aesthetics Clinic. Only authentic, permission-verified feedback is published.','/reviews');
export default function Page(){const approved=reviews.filter(r=>r.permissionVerified&&r.sourceUrl&&r.text&&r.attribution);return <div className="section page reviews-page"><span className="eyebrow">REVIVE / CLIENT VOICES</span><h1>What our<br/><em>clients say.</em></h1><p className="lede">Personal experiences deserve to be shared thoughtfully. This space is reserved for authentic client feedback, published with permission.</p>{approved.length?<div className="review-grid">{approved.map(r=><figure className="review-entry" key={r.id}><Quote size={30} aria-hidden="true"/><blockquote>{r.text}</blockquote><figcaption>{r.attribution}</figcaption><a href={r.sourceUrl} target="_blank" rel="noreferrer">Read the original review<ArrowUpRight size={16} aria-hidden="true"/></a></figure>)}</div>:<div className="reviews-empty"><Quote size={48} strokeWidth={1} aria-hidden="true"/><h2>Real voices.<br/><em>Shared with care.</em></h2><p>Verified client reviews have not yet been supplied. We will add them here once their source and permission to publish are confirmed.</p><div><ShieldCheck size={20} aria-hidden="true"/><span>Authentic feedback. No invented ratings or results.</span></div></div>}<div className="review-next"><MessageCircle size={26} aria-hidden="true"/><div><h3>Your questions matter.</h3><p>Explore your options in a consultation and decide what feels right for you.</p></div><Link href="/online-consultation" className="button">Book online<ArrowUpRight size={18} aria-hidden="true"/></Link></div></div>}
''')
# Wire routes into existing journeys.
p=r/'components/Footer.tsx';s=p.read_text(encoding='utf-8').replace('<Link href="/journal">The journal</Link>','<Link href="/journal">The journal</Link><Link href="/reviews">What our clients say</Link><Link href="/online-consultation">Book online</Link>');put('components/Footer.tsx',s)
p=r/'app/contact/page.tsx';s=p.read_text(encoding='utf-8');s="import Link from 'next/link';\n"+s;s=s.replace('<div className="contact-grid">','<div className="contact-online-link"><Link className="button" href="/online-consultation">Book an online consultation<ArrowUpRight size={18} aria-hidden="true"/></Link><p>Confirm availability, fee and payment instructions before booking.</p></div><div className="contact-grid">');put('app/contact/page.tsx',s)
p=r/'components/Consultation.tsx';s=p.read_text(encoding='utf-8').replace('Request a consultation','Request a consultation').replace('</Link></div><div className="consultation-interactive">','</Link><Link className="text-link online-inline" href="/online-consultation">Prefer an online consultation?<ArrowUpRight size={18} aria-hidden="true"/></Link></div><div className="consultation-interactive">');put('components/Consultation.tsx',s)
p=r/'app/sitemap.ts';s=p.read_text(encoding='utf-8').replace("'/contact',","'/contact','/reviews','/online-consultation',");put('app/sitemap.ts',s)
p=r/'.env.example';s=p.read_text(encoding='utf-8');s+='\n# Confirm the clinic-owned international WhatsApp number before enabling.\nNEXT_PUBLIC_WHATSAPP_NUMBER=\nNEXT_PUBLIC_WHATSAPP_VERIFIED=false\n';put('.env.example',s)
